private AbstractPolicy loadObjectPolicy(String pid)
 throws ServerException {
    try {
        DOReader reader = m_repoReader.getReader(Server.USE_DEFINITIVE_STORE, ReadOnlyContext.EMPTY, pid);
        Datastream ds = reader.GetDatastream("POLICY", null);
        if (ds != null) {
            logger.debug("Using POLICY for " + pid);
            return m_policyParser
                    .copy().parse(ds.getContentStream(),
                               m_validateObjectPoliciesFromDatastream);
        } else {
            return null;
        }
    } catch (ObjectNotInLowlevelStorageException e) {
        return null;
    }
}

