@Override
public InputStream getContentStream() throws StreamIOException {
    try {
        MIMETypedStream stream = getExternalContentManager().getExternalContent(new ContentManagerParams(DSLocation));
        DSSize = getContentLength(stream);
        return stream.getStream();
    } catch (Exception ex) {
